tests:
test({ sr: 'nalazi tekst bez obzira na velika slova', en: 'finds the text regardless of letter case' }, () => {
  expect(containsIgnoreCase('Hello World', 'world')).toBe(true);
});
test({ sr: 'tekst koga nema daje false', en: 'text that is missing gives false' }, () => {
  expect(containsIgnoreCase('Hello', 'xyz')).toBe(false);
});
test({ sr: 'prazan tekst ne sadrži slovo', en: 'an empty text does not contain a letter' }, () => {
  expect(containsIgnoreCase('', 'a')).toBe(false);
});

hiddenTests:
test('an empty search is found in every text', () => {
  expect(containsIgnoreCase('abc', '')).toBe(true);
  expect(containsIgnoreCase('', '')).toBe(true);
});
test('capital letters on either side', () => {
  expect(containsIgnoreCase('ABC', 'abc')).toBe(true);
  expect(containsIgnoreCase('abc', 'ABC')).toBe(true);
});
test('a search longer than the text is not found', () => {
  expect(containsIgnoreCase('abc', 'abcd')).toBe(false);
});
test('the match can be at the start, in the middle or at the end', () => {
  expect(containsIgnoreCase('Hello World', 'HELLO')).toBe(true);
  expect(containsIgnoreCase('Hello World', 'o W')).toBe(true);
  expect(containsIgnoreCase('Hello World', 'LD')).toBe(true);
});
